// Kontrollerar F32 "Tillgänglighet": språk, märkning, hopplänk, ärligt mål, tabellhuvud, inga externa resurser, ingen lagring,
// och F34: interna länkar utan .html (vercel.json har cleanUrls).
// AI-skapat (B-051). Generated by AI, Directed by MS.
const fs = require('fs');
const html = fs.readFileSync('public/tillganglighet.html', 'utf8');
const utanKommentarer = html.replace(/<!--[\s\S]*?-->/g, '');
const krav = {
  svenska: /<html lang="sv">/.test(html),
  titel: /<title>Tillgänglighet – luminusloom\.net<\/title>/.test(html),
  hopplankForst: html.indexOf('class="hoppa"') > -1 && html.indexOf('class="hoppa"') < html.indexOf('<header'),
  mainId: /<main id="innehall">/.test(html),
  aiEtiketter: (html.match(/class="etikett">AI-skapat</g) || []).length >= 2,
  signatur: (html.match(/Generated by AI, Directed by MS/g) || []).length >= 2,
  wcagSomMal: html.includes('WCAG 2.1') && html.includes('inte ett löfte'),
  tabellhuvud: (html.match(/<th scope="col">/g) || []).length === 2 && html.includes('<caption>'),
  ingetKontaktlofte: !/mailto:|@[a-z0-9-]+\.[a-z]/i.test(html),
  lankAiSida: html.includes('href="/sa-marker-vi-ai"'),
  ingaExterna: !/(src|href)="https?:\/\//.test(html) && !/@import|url\(/.test(html),
  ingetSkript: !/<script/i.test(html),
  ingenLagring: !/localStorage|sessionStorage|document\.cookie/.test(html),
  morktLage: html.includes('prefers-color-scheme: dark'),
  renaLankar: !/href="\/[^"]*\.html"/.test(utanKommentarer),
};
const ok = Object.values(krav).every(Boolean);
console.log(JSON.stringify({ ...krav, ok }));
process.exit(ok ? 0 : 1);
